import{_ as a,o as d,c as r,a5 as e}from"./chunks/framework.R-FQ1xZ2.js";const c=JSON.parse('{"title":"架构图库","description":"","frontmatter":{"title":"架构图库"},"headers":[],"relativePath":"diagrams/index.md","filePath":"diagrams/index.md","lastUpdated":null}'),l={name:"diagrams/index.md"};function h(n,t,i,o,s,m){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="架构图库" tabindex="-1">架构图库 <a class="header-anchor" href="#架构图库" aria-label="Permalink to &quot;架构图库&quot;">​</a></h1><p>共 <strong>43</strong> 张图，已生成 <strong>43</strong> 张。全部用 archify 绘制，可缩放、可切明暗主题、可导出 PNG/SVG。</p><blockquote><p>建议顺序：先看图建立整体印象 → 再读对应的知识体系笔记 → 最后用自己的话把图复述一遍。</p></blockquote><h2 id="agent-核心架构" tabindex="-1">Agent 核心架构 <a class="header-anchor" href="#agent-核心架构" aria-label="Permalink to &quot;Agent 核心架构&quot;">​</a></h2><p>Agent 是什么、怎么跑起来、循环怎么终止、多个 Agent 怎么协作。这一组是 AI Agent 岗的必答题。</p><table tabindex="0"><thead><tr><th>图</th><th>类型</th><th>一句话</th></tr></thead><tbody><tr><td><a href="/learn/diagrams/agent-architecture-overview.html">Agent 架构全景</a></td><td>架构图</td><td>把一个 Agent 拆成模型、工具、记忆、规划器、执行器五块，说清谁在什么时候调用谁。</td></tr><tr><td><a href="/learn/diagrams/react-loop.html">ReAct 循环时序</a></td><td>时序图</td><td>Reason → Act → Observe 一轮一轮怎么转，以及它为什么会停不下来。</td></tr><tr><td><a href="/learn/diagrams/plan-and-execute.html">Plan-and-Execute 工作流</a></td><td>流程图</td><td>先一次性拆解任务再逐步执行，比 ReAct 少绕路但更怕计划本身是错的。</td></tr><tr><td><a href="/learn/diagrams/multi-agent-topologies.html">多智能体协作拓扑</a></td><td>架构图</td><td>Supervisor、Network、Hierarchical、Sequential 四种协作形态，以及各自什么时候会变成灾难。</td></tr><tr><td><a href="/learn/diagrams/workflow-vs-agent.html">工作流 vs Agent</a></td><td>架构图</td><td>同样是 LLM 应用，什么时候该写死流程，什么时候才该让模型自己决定下一步。</td></tr><tr><td><a href="/learn/diagrams/agent-memory-taxonomy.html">Agent 记忆系统分类</a></td><td>架构图</td><td>短期 / 长期、原文 / 摘要 / 向量，四种记忆形态各自的成本与保真度。</td></tr></tbody></table><h2 id="框架与运行时" tabindex="-1">框架与运行时 <a class="header-anchor" href="#框架与运行时" aria-label="Permalink to &quot;框架与运行时&quot;">​</a></h2><p>LangChain 的抽象分层与 LangGraph 的图执行模型。面试官问「你用的框架底层做了什么」，答案在这一组。</p><table tabindex="0"><thead><tr><th>图</th><th>类型</th><th>一句话</th></tr></thead><tbody><tr><td><a href="/learn/diagrams/langchain-ecosystem.html">LangChain 抽象分层</a></td><td>架构图</td><td>Model I/O、Retrieval、Chains、Agents、Memory、Callbacks 六层抽象，以及它们的依赖方向。</td></tr><tr><td><a href="/learn/diagrams/langgraph-runtime.html">LangGraph 运行时</a></td><td>架构图</td><td>State、Node、Edge、Checkpointer、Store 五件套，以及一次 invoke 在图里到底走了什么。</td></tr></tbody></table><h2 id="工具与协议" tabindex="-1">工具与协议 <a class="header-anchor" href="#工具与协议" aria-label="Permalink to &quot;工具与协议&quot;">​</a></h2><p>Function Calling 的消息往返、MCP 的三层架构与授权、一次工具调用从发起到落库的完整生命周期。</p><table tabindex="0"><thead><tr><th>图</th><th>类型</th><th>一句话</th></tr></thead><tbody><tr><td><a href="/learn/diagrams/function-calling-flow.html">Function Calling 消息往返</a></td><td>时序图</td><td>从工具描述进 prompt，到模型吐出 tool_calls，再到结果回灌的完整四段往返。</td></tr><tr><td><a href="/learn/diagrams/mcp-architecture.html">MCP 三层架构</a></td><td>架构图</td><td>Host / Client / Server 三层，以及 Tools、Resources、Prompts 三类原语各管什么。</td></tr><tr><td><a href="/learn/diagrams/tool-call-lifecycle.html">工具调用生命周期</a></td><td>状态图</td><td>一次工具调用从被模型选中，到参数校验、执行、幂等保护、结果回灌、审计落库的六个阶段。</td></tr></tbody></table><h2 id="大模型基础" tabindex="-1">大模型基础 <a class="header-anchor" href="#大模型基础" aria-label="Permalink to &quot;大模型基础&quot;">​</a></h2><p>Transformer 整体结构、单个 Block 内部、注意力数据流与张量形状、一次推理的完整管线。大模型开发岗必考。</p><table tabindex="0"><thead><tr><th>图</th><th>类型</th><th>一句话</th></tr></thead><tbody><tr><td><a href="/learn/diagrams/transformer-architectures.html">Transformer 整体结构</a></td><td>架构图</td><td>Encoder-Decoder、Decoder-only、Encoder-only 三种形态的分工，以及为什么今天的大模型几乎都是 Decoder-only。</td></tr><tr><td><a href="/learn/diagrams/transformer-block.html">Transformer 单个 Block</a></td><td>架构图</td><td>一个 Block 内部从输入到输出的完整数据通路：自注意力、残差、归一化、前馈网络。</td></tr><tr><td><a href="/learn/diagrams/attention-dataflow.html">注意力数据流与张量形状</a></td><td>数据流图</td><td>Q、K、V 从哪来、怎么算、张量形状怎么变，以及多头到底拆的是什么。</td></tr><tr><td><a href="/learn/diagrams/llm-inference-pipeline.html">LLM 推理管线</a></td><td>数据流图</td><td>从文本进来到 token 出去：分词、Prefill、Decode、采样、流式返回的全过程。</td></tr></tbody></table><h2 id="检索增强生成" tabindex="-1">检索增强生成 <a class="header-anchor" href="#检索增强生成" aria-label="Permalink to &quot;检索增强生成&quot;">​</a></h2><p>RAG 端到端链路、混合检索与重排的内部结构。RAG 是面试考察最密的领域，会连问三层。</p><table tabindex="0"><thead><tr><th>图</th><th>类型</th><th>一句话</th></tr></thead><tbody><tr><td><a href="/learn/diagrams/rag-pipeline.html">RAG 端到端管线</a></td><td>数据流图</td><td>离线索引与在线问答两条链路，以及在哪些位置可以插质量改进点。</td></tr><tr><td><a href="/learn/diagrams/hybrid-retrieval-rerank.html">混合检索与重排</a></td><td>数据流图</td><td>稠密与稀疏两路怎么各自召回、分数怎么融合、重排器在哪个位置介入。</td></tr></tbody></table><h2 id="训练与微调" tabindex="-1">训练与微调 <a class="header-anchor" href="#训练与微调" aria-label="Permalink to &quot;训练与微调&quot;">​</a></h2><p>预训练 / SFT / 对齐的分工与数据管线，LoRA 等参数高效微调方法的注入位置。</p><table tabindex="0"><thead><tr><th>图</th><th>类型</th><th>一句话</th></tr></thead><tbody><tr><td><a href="/learn/diagrams/finetuning-taxonomy.html">训练与微调方法分类</a></td><td>架构图</td><td>预训练、SFT、对齐三阶段的分工，以及全参微调与 LoRA 等参数高效方法的取舍。</td></tr></tbody></table><h2 id="yyhelp-v2-项目图" tabindex="-1">YYHelp v2 项目图 <a class="header-anchor" href="#yyhelp-v2-项目图" aria-label="Permalink to &quot;YYHelp v2 项目图&quot;">​</a></h2><p>电商客服多轮对话 Agent：编排、工具、记忆、检索、灰度、评测、飞轮、可观测。以 v2 最终版为准，v1 只用于讲演进原因。</p><table tabindex="0"><thead><tr><th>图</th><th>类型</th><th>一句话</th></tr></thead><tbody><tr><td><a href="/learn/diagrams/yyhelp-arch-overview.html">YYHelp v2 全景架构</a></td><td>架构图</td><td>一个电商客服 Agent 的分层结构：接入层、编排层、能力层、数据层、观测层。</td></tr><tr><td><a href="/learn/diagrams/yyhelp-graph-topology.html">LangGraph 主图拓扑</a></td><td>架构图</td><td>意图怎么分流、专家怎么被调度、所有分支又怎么汇合回同一个执行循环。</td></tr><tr><td><a href="/learn/diagrams/yyhelp-v1-vs-v2.html">v1 → v2 演进对照</a></td><td>架构图</td><td>左右两个版本并排看，每一处改动都要能回答「为什么改」。</td></tr><tr><td><a href="/learn/diagrams/yyhelp-execution-loop.html">核心执行循环时序</a></td><td>时序图</td><td>一轮对话里，模型、执行器、工具、状态之间往返还手了哪些消息。</td></tr><tr><td><a href="/learn/diagrams/yyhelp-specialist-visibility.html">专家与工具可见性矩阵</a></td><td>架构图</td><td>同一个工具池，不同的专家只看得见其中一部分——为什么，以及怎么验证。</td></tr><tr><td><a href="/learn/diagrams/yyhelp-tool-mcp.html">工具层与 MCP 边界</a></td><td>架构图</td><td>原生工具与 MCP 工具并存，各自负责什么、边界画在哪、以及为什么这么分。</td></tr><tr><td><a href="/learn/diagrams/yyhelp-tool-call-lifecycle.html">写操作生命周期与幂等</a></td><td>状态图</td><td>一次「建工单」从模型提出意图到真正落库，中间要过哪几道门。</td></tr><tr><td><a href="/learn/diagrams/yyhelp-memory-checkpoint.html">记忆写入与检查点恢复</a></td><td>状态图</td><td>会话状态怎么被存下来、进程重启后怎么接上、长期记忆什么时候写、什么时候读。</td></tr><tr><td><a href="/learn/diagrams/yyhelp-retrieval-dual.html">Milvus 单库双路检索</a></td><td>数据流图</td><td>稠密向量和稀疏向量放在同一个库里、同一套 API 检索，融合以后进业务。</td></tr><tr><td><a href="/learn/diagrams/yyhelp-canary-routing.html">灰度分流与模型路由</a></td><td>流程图</td><td>请求怎么被分到不同的执行模式与不同价位的模型上，以及分流必须满足什么条件。</td></tr><tr><td><a href="/learn/diagrams/yyhelp-ab-statistics.html">AB 配对检验与三态结论</a></td><td>流程图</td><td>两条执行路径拿同一批题做配对盲测，怎么算、怎么判、什么情况必须承认测不出来。</td></tr><tr><td><a href="/learn/diagrams/yyhelp-flywheel.html">数据飞轮闭环</a></td><td>数据流图</td><td>线上失败样本怎么回到离线、怎么判断失败原因、怎么变成下一轮改进的输入。</td></tr><tr><td><a href="/learn/diagrams/yyhelp-observability.html">双后端可观测与显式降级</a></td><td>架构图</td><td>一套埋点同时送两个后端，其中一个挂了不能影响业务，而且降级要留下证据。</td></tr><tr><td><a href="/learn/diagrams/yyhelp-request-flow.html">一次请求的数据流全景</a></td><td>时序图</td><td>把前面所有图串起来：一个真实问题从进来到流式吐字，中间经过了什么。</td></tr></tbody></table><h2 id="科研文献-rag-项目图" tabindex="-1">科研文献 RAG 项目图 <a class="header-anchor" href="#科研文献-rag-项目图" aria-label="Permalink to &quot;科研文献 RAG 项目图&quot;">​</a></h2><p>面向无人水面艇与多智能体强化学习文献的检索问答服务：离线索引、双路召回、拒答、评测、门禁、服务化。</p><table tabindex="0"><thead><tr><th>图</th><th>类型</th><th>一句话</th></tr></thead><tbody><tr><td><a href="/learn/diagrams/rag-arch-overview.html">科研文献 RAG 全景架构</a></td><td>架构图</td><td>一张图看清离线索引、在线问答、横切能力、评测闭环四个分区各自管什么、谁调用谁。</td></tr><tr><td><a href="/learn/diagrams/rag-offline-indexing.html">离线索引流水线</a></td><td>数据流图</td><td>从 PDF 到可检索索引，中间每一步的输入输出与落盘产物。</td></tr><tr><td><a href="/learn/diagrams/rag-chunking-pipeline.html">切块策略与分档消融</a></td><td>流程图</td><td>同一批文档用不同切法切出来，检索质量差在哪里、为什么。</td></tr><tr><td><a href="/learn/diagrams/rag-dual-retrieval.html">双路召回、RRF 融合与精排</a></td><td>数据流图</td><td>稠密路与稀疏路各自召回，怎么融合、怎么精排、最后怎么拼上下文。</td></tr><tr><td><a href="/learn/diagrams/rag-sparse-selfcheck.html">稀疏路自检失效（SPARSE_MODE=overlap）</a></td><td>流程图</td><td>让程序自己判断「这次要不要用稀疏路」，而不是永远开或永远关。</td></tr><tr><td><a href="/learn/diagrams/rag-guard-two-layer.html">双层拒答决策流</a></td><td>流程图</td><td>程序层用分数阈值零成本拦一道，模型层再自报一次，两层误拒率分开测。</td></tr><tr><td><a href="/learn/diagrams/rag-eval-harness.html">分层评测体系</a></td><td>架构图</td><td>检索侧和生成侧是两套独立的评测对象，指标不同、样本不同、结论不能互相代替。</td></tr><tr><td><a href="/learn/diagrams/rag-regression-gate.html">回归门禁与三态退出码</a></td><td>流程图</td><td>把评测中确定性的那部分抽出来做成能进 CI 的门禁，用退出码表达三种结论。</td></tr><tr><td><a href="/learn/diagrams/rag-serving-lifecycle.html">服务冷启动到稳态</a></td><td>状态图</td><td>从进程起来到能扛流量，中间要过的几道状态，以及为什么健康检查不能只做一个。</td></tr><tr><td><a href="/learn/diagrams/rag-request-latency.html">一次问答的延迟分解</a></td><td>时序图</td><td>一个请求从进来到第一个字出去，时间到底花在哪一步。</td></tr><tr><td><a href="/learn/diagrams/rag-vs-yyhelp-boundary.html">前作与 YYHelp 的能力边界</a></td><td>架构图</td><td>两个项目不是「一个升级版」，而是回答了两个不同的问题。</td></tr></tbody></table>',27)])])}const f=a(l,[["render",h]]);export{c as __pageData,f as default};
